import{_ as i,a0 as u,w as o,s,I as e,x as r,a1 as p,A as n,ao as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"前瞻：Xfce 4.18 主要新功能 | LCTT x X-CMD","titleTemplate":false,"description":"前瞻：Xfce 4.18 主要新功能 | LCTT (202211) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"前瞻：Xfce 4.18 主要新功能 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"前瞻：Xfce 4.18 主要新功能 | LCTT (202211) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202211/20221103.3 ⭐️⭐️ Xfce 4.18 Top New Features & Release Guide","title":"前瞻：Xfce 4.18 主要新功能","tag":"202211","desc":""},"relativePath":"202211/20221103.3 ⭐️⭐️ Xfce 4.18 Top New Features & Release Guide.md","filePath":"[post].md"}'),d={name:"202211/20221103.3 ⭐️⭐️ Xfce 4.18 Top New Features & Release Guide.md"};function f(b,t,w,m,g,y){const l=u("Link");return o(),s("div",null,[t[33]||(t[33]=e("h1",{id:"前瞻-xfce-4-18-主要新功能",tabindex:"-1"},[r("前瞻：Xfce 4.18 主要新功能 "),e("a",{class:"header-anchor",href:"#前瞻-xfce-4-18-主要新功能","aria-label":"Permalink to “前瞻：Xfce 4.18 主要新功能”"},"​")],-1)),t[34]||(t[34]=e("blockquote",null,[e("p",null,"有關 Xfce 4.18 的核心和原生應用程序的功能的全面介紹。")],-1)),e("p",null,[t[1]||(t[1]=r("經過近兩年的開發，Xfce 4.18 將在 2022 年聖誕節期間發佈。作為 ",-1)),p(l,{href:"https://www.debugpoint.com/xfce-4-16-review/"},{default:n(()=>[...t[0]||(t[0]=[r("Xfce 4.16",-1)])]),_:1}),t[2]||(t[2]=r(" 以來的重要的版本，其一直在開發標籤 4.17 下進行開發，以增強這個輕量級桌面。",-1))]),t[35]||(t[35]=a('<p>考慮到 GTK4 的更新、初步的 Wayland 支持，以及核心和本地應用程序的改進，Xfce 4.18 是一個重要的里程碑版本，其帶來了大量更新。</p><p>從發佈時間來看，第一個 Xfce 4.18 預發佈版（pre1）已經發布。2022 年 12 月的第一週會有另一個預發佈版。而 Xfce 4.18 的最終版本預計將在 2022 年 12 月 15 日至 12 月 29 日之間發佈。</p><p>由於目前還沒有官方的詳細介紹，我在這篇文章中總結了 Xfce 4.18 的基本和主要功能。</p><p>請繼續閲讀。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/11/Xfce-4.18-pre1-compiled-in-Arch-1024x594.jpg" alt="Xfce 4.18 pre1 (compiled in Arch)"></p><h3 id="xfce-4-18-的新功能" tabindex="-1">Xfce 4.18 的新功能 <a class="header-anchor" href="#xfce-4-18-的新功能" aria-label="Permalink to “Xfce 4.18 的新功能”">​</a></h3><h4 id="_1、核心庫更新" tabindex="-1">1、核心庫更新 <a class="header-anchor" href="#_1、核心庫更新" aria-label="Permalink to “1、核心庫更新”">​</a></h4><p>Xfce 4.18 的依賴關係有所改變，並使用以下版本進行編譯：</p><ul><li>glib-2.0 &gt;= 2.66</li><li>gtk &gt;= 3.24</li><li>libcairo &gt;= 1.16</li><li>gdk-pixbuf-2.0 &gt;= 2.40</li><li>gobject-introspection &gt;= 1.66</li></ul><h4 id="_2、桌面和麪板" tabindex="-1">2、桌面和麪板 <a class="header-anchor" href="#_2、桌面和麪板" aria-label="Permalink to “2、桌面和麪板”">​</a></h4><p>頂部的主面板帶來了新的設置和調整。但整體外觀仍與以前的 4.16 版本中的一樣。一些默認的面板小程序在這個版本中也有變化。桌面圖標、右鍵上下文菜單和項目保持不變。</p><p>面板的首選項設置有兩個新的選項。首先，面板的長度現在以<strong>像素</strong>設置，而不是百分比。其次，一個新的選項，“<ruby>保持面板在窗口上方<rt>Keep panel above windows</rt></ruby>” ，可以讓你將窗口對話放到面板後面。之前，應用程序的窗口只能達到面板的邊緣。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/11/Panel-preferences-in-Xfce-4.18.jpg" alt="Xfce 4.18 中的面板首選項"></p><p>徹底修改了時鐘小程序的設置。是的，你終於可以改變 Xfce 時鐘小程序的字體風格。與此同時，它提供了四種時鐘佈局：</p><ul><li>只有日期</li><li>只有時間</li><li>日期和時間</li><li>時間和日期</li></ul><p>此外，你還可以向日歷中添加命令。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/11/Finally-you-can-change-the-font-of-Xfce-Clock-applet.jpg" alt="終於你可以改變 Xfce 時鐘小程序的字體了"></p><h4 id="_3、thunar-文件管理器" tabindex="-1">3、Thunar 文件管理器 <a class="header-anchor" href="#_3、thunar-文件管理器" aria-label="Permalink to “3、Thunar 文件管理器”">​</a></h4><p>也許這個版本中最令人興奮的變化是 Thunar 文件管理器的功能。首先，一個新的“搜索”圖標取代了工具欄上的“重新加載”按鈕。當點擊時，它會在地址欄上出現搜索，可以使用你的搜索關鍵詞進行遞歸搜索。重新加載按鈕被放到了 “<ruby>查看<rt>View</rt></ruby>” 菜單中。</p><p>其次，在左邊的導航欄上增加了一個的新項目，“<ruby>最近<rt>Recent</rt></ruby>”。在底部，元數據更有條理（從逗號分隔改為豎線分隔），還有一個新的上下文菜單項可以選擇你想要顯示的元數據。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/11/Thunar-4.18-visual-changes.jpg" alt="Thunar 4.18 的視覺變化"></p><p>Thunar 的主菜單有很多變化。下面列出了主要的變化。在下面的圖片中還標註了自 4.16 以來的變化。</p><ul><li>引入了一個<strong>新的書籤菜單</strong>，可以將當前文件夾作為快捷方式添加到側邊欄。</li><li>“<ruby>編輯<rt>Edit</rt></ruby>”菜單有了 “<ruby>撤銷<rt>undo</rt></ruby>” 和 “<ruby>重做<rt>redo</rt></ruby>” 選項。</li><li>“<ruby>前往<rt>Go</rt></ruby>” 菜單有了 “<ruby>最近<rt>Recent</rt></ruby>” 和 “<ruby>搜索<rt>Search</rt></ruby>” 的選項。</li></ul><p>Thunar 首次通過 “<ruby>視圖<rt>View</rt></ruby>”菜單項有了“<ruby>分割視圖<rt>Split view</rt></ruby>”！ 是的，你現在可以在視圖面板中拖放項目。</p>',24)),e("p",null,[t[4]||(t[4]=r("前不久，我 ",-1)),p(l,{href:"https://debugpointnews.com/thunar-image-preview/"},{default:n(()=>[...t[3]||(t[3]=[r("報道",-1)])]),_:1}),t[5]||(t[5]=r(" 説圖像預覽即將在 Thunar 中出現。而它終於來了。作為谷歌代碼之夏 2022 的部分開發成果，你現在可以嵌入在側邊欄中看到圖片預覽。或者在右邊的一個獨立的新面板上查看。它可以通過偏好設置來改變。",-1))]),t[36]||(t[36]=a('<p>下面是它的外觀。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/11/Thunar-split-view-with-embedded-image-preview.jpg" alt="帶有獨立圖像預覽的 Thunar 分割視圖"></p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/11/Thunar-split-view-with-sidebar-image-preview.jpg" alt="嵌入圖像預覽的 Thunar 分割視圖"></p><h4 id="_4、thunar-的首選項" tabindex="-1">4、Thunar 的首選項 <a class="header-anchor" href="#_4、thunar-的首選項" aria-label="Permalink to “4、Thunar 的首選項”">​</a></h4><p>Thunar 設置中出現了大量調整。首先，一個新的選項卡可以為 Thunar 定製你的鍵盤快捷鍵。你可以直接指定新的快捷鍵組合，並從這個選項卡中改變現有的快捷鍵組合。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/11/New-shortcut-tab-in-Thunar.jpg" alt="Thunar 的新快捷鍵標籤"></p><p>“<ruby>顯示<rt>Display</rt></ruby>” 設置中新增了一個縮略圖部分，你現在可以指定縮略圖的文件大小。縮略圖的具體設置也被歸為一組。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/11/Thunar-Display-Settings-in-4.18.jpg" alt="4.18 版的 Thunar 顯示設置"></p><p>“<ruby>側面板<rt>Side Pane</rt></ruby>” 選項卡有了一個新的圖像預覽選項，你在上面看到過。你可以設置為嵌入式或獨立式預覽。此外，“<ruby>行為<rt> Behaviour</rt></ruby>” 選項卡增加了 “<ruby>啓動時恢復選項卡<rt>restore tabs on startup</rt></ruby>” 和在選項卡標題中顯示 “<ruby>完整的目錄路徑<rt>full directory path</rt></ruby>” 的選項，這將有很大幫助。</p><p>“<ruby>高級<rt>Advanced</rt></ruby>” 選項卡為 “<ruby>文件傳輸<rt>File Transfer</rt></ruby>” 提供了一個新的設置部分，有兩個新的選項：“<ruby>中間文件複製<rt>Intermediate file copy</rt></ruby>”和“<ruby>驗證校驗和<rt>Verify checksum</rt></ruby>”。此外，在這個選項卡中還增加了一個新的遞歸搜索的選項。你還可以通過以下選項將 Thunar 設置為直接 “<ruby>執行 Shell 腳本<rt>Execute Shell script</rt></ruby>”。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/11/Advanced-options-of-Thunar-4.18.jpg" alt="Thunar 4.18 的高級選項"></p><p>除了上述變化外，文件夾屬性對話框現在可以顯示文件和文件夾的數量。另外，一個新的高亮選項使你能夠為你的文件夾圖標背景和前景選擇任何自定義顏色。如果你有一個複雜的文件夾結構，這將使你能夠快速導航。</p><p>下面是它的外觀。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/11/Folder-highlight-demo.jpg" alt="文件夾高亮演示"></p><h4 id="設置" tabindex="-1">設置 <a class="header-anchor" href="#設置" aria-label="Permalink to “設置”">​</a></h4><p>“<ruby>外觀<rt>Appearances</rt></ruby>” 設置現在允許你打開和關閉對話框的標題欄。</p><p>“<ruby>桌面<rt>Desktop</rt></ruby>” 設置允許文件上下文菜單中的刪除選項（打開或關閉）。</p><p>“<ruby>顯示<rt>Display</rt></ruby>” 設置現在允許你為多種顯示情況設置默認值：鏡像、擴展顯示還是什麼都不做。早些時候，這些選項在顯示器被連接時才可用。</p><h4 id="wayland-和其他更新" tabindex="-1">Wayland 和其他更新 <a class="header-anchor" href="#wayland-和其他更新" aria-label="Permalink to “Wayland 和其他更新”">​</a></h4><p>除了上述 Xfce 4.18 的功能外，窗口管理器和桌面還有許多額外的錯誤修復和性能改進。這些都是在底層的，你應該能感受到一個更精良的 Xfce 桌面體驗。</p>',20)),e("p",null,[t[7]||(t[7]=r("Xfce 桌面核心和原生應用程序的 Wayland 遷移工作開始了。離它完全準備好還有很長的路要走。在這個版本中，你可能不會看到很多 Wayland 的更新。然而，許多應用程序在 Wayland 下已經可以正常工作了。你可以在 ",-1)),p(l,{href:"https://wiki.xfce.org/releng/wayland_roadmap"},{default:n(()=>[...t[6]||(t[6]=[r("本頁",-1)])]),_:1}),t[8]||(t[8]=r(" 瞭解更多關於遷移狀態的信息。",-1))]),t[37]||(t[37]=e("h3",{id:"下載及什麼時候出現在發行版",tabindex:"-1"},[r("下載及什麼時候出現在發行版 "),e("a",{class:"header-anchor",href:"#下載及什麼時候出現在發行版","aria-label":"Permalink to “下載及什麼時候出現在發行版”"},"​")],-1)),e("p",null,[t[10]||(t[10]=r("Xfce 4.18 應該會在 2023 年 4 月進入 Ubuntu 23.04 Lunar Lobster，並在 Fedora 38 中出現。基於滾動發佈的發行版，如 Arch Linux、Manjaro 和 OpenSUSE Tumbleweed 應該會在 2022 年 12 月發佈後的幾天內得到它。輕量級的流行發行版 ",-1)),p(l,{href:"https://www.debugpoint.com/tag/mx-linux"},{default:n(()=>[...t[9]||(t[9]=[r("MX Linux",-1)])]),_:1}),t[11]||(t[11]=r(" 應該在 2023 年採用這個版本，這個時候也是 Debian Bookworm 更新的時候。",-1))]),e("p",null,[t[14]||(t[14]=r("Xfce 4.18 的第一個預發佈版本 ",-1)),p(l,{href:"https://www.reddit.com/r/xfce/comments/yjiwwv/announce_xfce_418pre1_released/"},{default:n(()=>[...t[12]||(t[12]=[r("現已發佈",-1)])]),_:1}),t[15]||(t[15]=r("。你可以從下面的頁面下載源碼壓縮包，並編譯它們。請參考官方的 ",-1)),p(l,{href:"https://docs.xfce.org/xfce/building"},{default:n(()=>[...t[13]||(t[13]=[r("編譯指南",-1)])]),_:1}),t[16]||(t[16]=r("。",-1))]),e("blockquote",null,[e("p",null,[e("strong",null,[p(l,{href:"https://archive.xfce.org/xfce/4.18pre1/fat_tarballs"},{default:n(()=>[...t[17]||(t[17]=[r("下載 Xfce 4.18 源代碼（pre1）",-1)])]),_:1})])])]),t[38]||(t[38]=e("h3",{id:"總結",tabindex:"-1"},[r("總結 "),e("a",{class:"header-anchor",href:"#總結","aria-label":"Permalink to “總結”"},"​")],-1)),t[39]||(t[39]=e("p",null,"總的來説，變化的數量巨大。許多核心變化和需要的變化都進入了這個版本。Thunar 文件管理器的更新是早該進行的，對於 Xfce 的愛好者來説應該是完美的。",-1)),t[40]||(t[40]=e("p",null,"隨着 Wayland 的支持，未來的 Xfce 版本可能會帶來一個可行的 Xfce 版本。Wayland 的支持仍在進行中，每個組件都有許多決定有待作出。許多發行版和關鍵部署仍然喜歡 Xfce 而不是 KDE Plasma 或 GNOME。考慮到這些用例和未來的路線圖，Xfce 4.18 是下一個版本之前的一個重要的里程碑。",-1)),t[41]||(t[41]=e("p",null,"列表中你最喜歡的功能是什麼？請在評論欄裏告訴我。",-1)),t[42]||(t[42]=e("hr",null,null,-1)),e("p",null,[t[19]||(t[19]=r("via: ",-1)),p(l,{href:"https://www.debugpoint.com/xfce-4-18-features/"},{default:n(()=>[...t[18]||(t[18]=[r("https://www.debugpoint.com/xfce-4-18-features/",-1)])]),_:1})]),e("p",null,[t[24]||(t[24]=r("作者：",-1)),p(l,{href:"https://www.debugpoint.com/author/admin1/"},{default:n(()=>[...t[20]||(t[20]=[r("Arindam",-1)])]),_:1}),t[25]||(t[25]=r(" 選題：",-1)),p(l,{href:"https://github.com/lkxed"},{default:n(()=>[...t[21]||(t[21]=[r("lkxed",-1)])]),_:1}),t[26]||(t[26]=r(" 譯者：",-1)),p(l,{href:"https://github.com/wxy"},{default:n(()=>[...t[22]||(t[22]=[r("wxy",-1)])]),_:1}),t[27]||(t[27]=r(" 校對：",-1)),p(l,{href:"https://github.com/wxy"},{default:n(()=>[...t[23]||(t[23]=[r("wxy",-1)])]),_:1})]),e("p",null,[t[30]||(t[30]=r("本文由 ",-1)),p(l,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[28]||(t[28]=[r("LCTT",-1)])]),_:1}),t[31]||(t[31]=r(" 原創編譯，",-1)),p(l,{href:"https://linux.cn/"},{default:n(()=>[...t[29]||(t[29]=[r("Linux中國",-1)])]),_:1}),t[32]||(t[32]=r(" 榮譽推出",-1))])])}const X=i(d,[["render",f]]);expor